    "descriptionHtml": "<h2><strong>150 LPH RO Plant -&nbsp;Doctor Fresh</strong></h2>\r\n\r\n<p>Doctor Fresh 150 LPH RO Plant is a stainless steel-made, RO, PSS technology-loaded RO plant that offers a maximum of 150 liters of water per hour. It has a fully automatic mode of operation with multi-stage purification stages. It can cater up to 1500 liter water per day when it is in the best shape.</p>\r\n\r\n<p>The activated carbon filter, multi-grade filter, and reverse osmosis filter give more than 50% water recovery rate. This becomes an excellent pick for you when you care about its repair and maintenance. It has an auto shut-off and TDS adjuster technology that offer double filtration benefits.</p>\r\n\r\n<h3><strong>Application of 150 LPH RO plant</strong></h3>\r\n\r\n<ul>\r\n\t<li>The 150 LPH commercial RO plant is best for large scale purpose</li>\r\n\t<li>It must be found in school, college, and other educational centers</li>\r\n\t<li>Used for business purposes and manufacturing plants</li>\r\n\t<li>It is best to install at commercial buildings and malls</li>\r\n</ul>",
    "installationHtml": "",
    "shippingHtml": "<ul>\r\n\t<li><strong>Tax</strong>: 18% GST Extra</li>\r\n\t<li><strong>Installation</strong>: 10% of the product cost.</li>\r\n\t<li><strong>Warranty</strong>: 1 Year warranty on electrical parts from the date of purchase.<br />\r\n\t<strong>Warranty Exclusion</strong>: Filters, media carbon, membranes, chemicals, and other consumables are not covered in the warranty policy.</li>\r\n\t<li>Electricity supply, availability of water supply, foundation, plastic, rubber and fitting item, and other accessories required will be borne by the client.</li>\r\n\t<li><strong>Freight Charges</strong>: Extra as on actual and will be decided mutually according to RO Plant Capacity and Client location.</li>\r\n\t<li><strong>Insurance </strong>- The insurance Charge will be extra.</li>\r\n\t<li><strong>Payment</strong>: 100% advance along with purchase order.</li>\r\n</ul>",
