    "descriptionHtml": "<h2><strong>Doctor Fresh 500 LPH RO Plant - Silver (RO)</strong></h2>\r\n\r\n<p>Doctor Fresh 500 LPH RO Plant is loaded with the top-quality RO, and TDS adjuster system. The silver-colored RO plant has the big blue filters to claim the 500-liter water per hour. The high pressure and anti-dosing pump give a boost to the flow meter to deliver the 5000 liters of water in a day.</p>\r\n\r\n<p>The Doctor Fresh 500 LPH RO plant model works well up to 1000 TDS level and has an auto cleaning function to reduce human interruptions. This model is a fully automatic machine with a maximum of 8-10 hours per day duty cycle.</p>\r\n\r\n<h3><strong>Advantages of using 500 LPH RO plant</strong></h3>\r\n\r\n<ul>\r\n\t<li>Get excellent water purification as it effectively removes hardness and other pollutants</li>\r\n\t<li>The sediment filter can cut out excess minerals and sediments present in water</li>\r\n\t<li>RO membrane reduces the majority of TDS</li>\r\n\t<li>Activated carbon filter to remove bad taste, odor, and color</li>\r\n\t<li>This model is suitable for both commercial and industrial purposes</li>\r\n</ul>",
    "installationHtml": "<table cellspacing=\"0\" style=\"border-collapse:collapse; width:718px\">\r\n\t<tbody>\r\n\t\t<tr>\r\n\t\t\t<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; height:57px; vertical-align:top; width:116px\">\r\n\t\t\t<p><strong>E</strong><strong>rection & Commissioning</strong></p>\r\n\t\t\t</td>\r\n\t\t\t<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:1px solid black; height:57px; vertical-align:top; width:603px\">\r\n\t\t\t<p><strong>Installation charges Extra and the site has to be ready before the installation, </strong>you will have to ensure and arrange provision of raw material, skilled/unskilled labor, electricity & Power Supply at the time of installation</p>\r\n\t\t\t</td>\r\n\t\t</tr>\r\n\t</tbody>\r\n</table>",
