    "descriptionHtml": "<h2><strong>Doctor Fresh 500 LPH RO Plant - Gold (RO+UV+TDS Adjuster + Iron Removal)</strong></h2>\r\n\r\n<p>Doctor Fresh 500 LPH RO Plant has a top-quality RO, UV, TDS adjuster, and iron removal system. The gold-colored RO plant has the big blue filters to deliver the 500-liter water per hour successfully. The high pressure and anti-dosing pump help the flow meter ensure the 5000 liters of water supply in a day.</p>\r\n\r\n<p>The Doctor Fresh 500 LPH RO plant gold model works comfortably around 800-1000 TDS level, and the auto cleaning function is there to reduce human interruption for manual cleaning. This fully automatic model offers an 8-10 hours continuous duty cycle every day.</p>\r\n\r\n<h3><strong>Benefits of using 500 LPH RO plant</strong></h3>\r\n\r\n<ul>\r\n\t<li>The 500 LPH RO Plant effectively removes hardness and other pollutants</li>\r\n\t<li>The sediment filter is used to reduce excess minerals and traces of sediments</li>\r\n\t<li>RO membrane is used to reduce the total hardness present in the water</li>\r\n\t<li>An activated carbon filter has the ability to neutralize bad taste, odor, and color</li>\r\n\t<li>This model is the best match for both commercial and industrial purposes</li>\r\n</ul>",
