    "descriptionHtml": "<h3><strong>Doctor Fresh 1000 LPH RO Plant - Platinum (RO+UV+TDS Adjuster + FSS)</strong></h3>\r\n\r\n<p>The <strong><a href=\"/\">Doctor Fresh</a></strong> 1000 LPH platinum RO Plant model has the best in class RO, UV, and FSS water purification system to cope with polluted water. The TDS adjuster and FSS technology is additionally working to keep the TDS level under consideration to help the big blue filter.</p>\r\n\r\n<p>The fully automatic 1000 LPH water purifying capacity platinum model RO plant is made of food-grade stainless steel and has an auto shut-off function. The best 1000 LPH RO plant model runs up to more than 3000 TDS level water in municipal or groundwater.</p>\r\n\r\n<h3><strong>The benefits of Doctor Fresh 1000 LPH RO Plant</strong></h3>\r\n\r\n<ul>\r\n\t<li>The 1000 LPH platinum edition RO plant system is suitable for all sources of water</li>\r\n\t<li>The smart RO+UV and TDS adjuster and FSS system work well up to 3000 <strong><a href=\"/blog/11/how-to-check-tds-of-water\">TDS level</a></strong></li>\r\n\t<li>High-pressure water pump and updated pressure gauge ensure its continuous water yield</li>\r\n\t<li>The <strong><a href=\"/category/ro-plant/1000-lph-ro-plant\">1000 LPH RO Plant</a></strong> is specially designed for industrial applications</li>\r\n\t<li>It gives you 8-10 hours uninterrupted working cycle in a day</li>\r\n</ul>",
