    "descriptionHtml": "<h3><strong>Doctor Fresh 3000 LPH RO Plant - Gold (RO+UV+TDS Adjuster +IRON Removal)</strong></h3>\r\n\r\n<p><a href=\"/\"><strong>Doctor Fresh</strong></a> 3000 LPH RO Plant (Gold) RO, UV, TDS adjuster and iron remover technology is used to deliver the required amount of water. The big blue filter and raw water pump help get the required quantity of water in a day. You can also attach sand and carbon filters and the <strong><a href=\"/category/ro-plant/3000-lph-ro-plant\">3000 LPH RO plant model</a></strong> as per the customer's need.</p>\r\n\r\n<p>The fully automatic 3000 LPH RO plant is basically an industrial machine with an automatic flush function to flush out denied water. It offers 110000 liters of water by a maximum of 20-22 hours maximum working cycle. The <strong><a href=\"/category/ro-plant\">RO plant</a></strong> components are made of food-grade material and certified membranes to deliver the best-in-class water.</p>\r\n\r\n<h3><strong>The benefits of having 3000 LPH RO plant</strong></h3>\r\n\r\n<ul>\r\n\t<li>The 3000 RO plant gives you 99.9% pure water</li>\r\n\t<li>The auto flush and cleaning technology makes it the best in business</li>\r\n\t<li>You can primarily use for industrial as well as commercial applications</li>\r\n\t<li>Get a maximum of 2000-3000 people's daily water requirement</li>\r\n</ul>",
    "installationHtml": "<table cellspacing=\"0\" style=\"border-collapse:collapse; width:718px\">\r\n\t<tbody>\r\n\t\t<tr>\r\n\t\t\t<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; height:57px; vertical-align:top; width:116px\">\r\n\t\t\t<p><strong>E</strong><strong>rection &amp; Commissioning</strong></p>\r\n\t\t\t</td>\r\n\t\t\t<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:1px solid black; height:57px; vertical-align:top; width:603px\">\r\n\t\t\t<p><strong>Installation charges Extra and the site has to be ready before the installation, </strong>you will have to ensure and arrange provision of raw material, skilled/unskilled labor, electricity &amp; Power Supply at the time of installation</p>\r\n\t\t\t</td>\r\n\t\t</tr>\r\n\t</tbody>\r\n</table>",
    "shippingHtml": "<ul>\r\n\t<li><strong>Tax</strong>: 18% GST Extra</li>\r\n\t<li><strong>Installation</strong>: 10% of the product cost.</li>\r\n\t<li><strong>Warranty</strong>: 1 Year warranty on electrical parts from the date of purchase.<br />\r\n\t<strong>Warranty Exclusion</strong>: Filters, media carbon, membranes, chemicals, and other consumables are not covered in the warranty policy.</li>\r\n\t<li>Electricity supply, availability of water supply, foundation, plastic, rubber and fitting item, and other accessories required will be borne by the client.</li>\r\n\t<li><strong>Freight Charges</strong>: Extra as on actual and will be decided mutually according to RO Plant Capacity and Client location.</li>\r\n\t<li><strong>Insurance </strong>- The insurance Charge will be extra.</li>\r\n\t<li><strong>Payment</strong>: 100% advance along with purchase order.</li>\r\n</ul>",
