    "descriptionHtml": "<p>With RO UV UF and TDS Infuser technology, Doctor Fresh Life Protector Plus water purifier is perfect for all water sources for Indian homes and small offices. Including RO UV UF & TDS infuser, this <a href=\"/category/water-purifier\">water purifier</a> has 7 stages for the purification process. This purifier eliminates even single molecules of dissolved impurities, bacteria, and viruses to make water 100% pure and healthy. The Doctor Fresh Life Protector Plus water purifier also restores essential minerals in the water. It also has 10 litres of plastic food graded storage tank to store pure and healthy water. Doctor Fresh Life Protector Plus RO with tds controller.</p>\r\n\r\n<ul>\r\n\t<li>Based on RO UV UF & TDS Infuser technology</li>\r\n\t<li>7-stage water purification process</li>\r\n\t<li>10 litres storage tank</li>\r\n\t<li>Suitable for home & offices</li>\r\n\t<li>1-year onsite warranty and 4 years of service warranty</li>\r\n</ul>",
    "installationHtml": "",
    "shippingHtml": "",
    "reviews": [],
    "faqs": [
      {
        "question": "Does Doctor Fresh Life Protector Plus RO+UV+UF+TDS Infuser remove excess TDS?",
        "answer": "When raw water goes through the RO membrane, physical and soil particles are strained. But, in the case of the TDS infuser, it can automatically flush out all the subtance causing high TDS like ions and metals. So, you can get customized water quality that can be stored for a long time without any further treatments."
      },
      {
        "question": "Why should I choose the Doctor Fresh Life Protector Plus RO+UV+UF+TDS Infuser water purifier?",
        "answer": "Life Protector Plus purifier has RO, UV, UF, and TDS infuser technology to produce pure water after 7 stage purification. Choose a Doctor Fresh water purifier and say no to water-related diseases and low TDS water. The best-in-class multi-stage filter offers you assured quality water having all essential minerals."
      },
      {
        "question": "How often should the Doctor Fresh Life Protector Plus RO+UV+UF+TDS Infuser water purifier filter be changed?",
        "answer": "Filters are the essential constituents of any water purifier, whether it has RO, UV, UF, TDS, or any other filters. All these filters need to be replaced once a year as they can be more or less as per usage and the incoming water quality. When the sediment filter is used in a water purifier, it reduces the damage to further water filters."
      },
      {
        "question": "How much does Doctor Fresh Life Protector Plus RO+UV+UF+TDS Infuser water purifier maintenance cost?",
        "answer": "No matter the water purifier model and brand, they all need maintenance to keep working at their full efficiency. After completion of one year, the frequency of service is a little higher as per the water pollution level and the gap between the previous repairs. Because of the high quality, durable filters, you don’t have to pay an unusual maintenance cost."
      }
    ]
